_CORE_SRC = '# Exact action format: {"moves": [(from_node, to_node, count), ...], "build": n_buy}\n# Payout: equal fleets serve capacity_p * demand / max(capacity_0 + capacity_1,\n# demand); otherwise the larger fleet serves min(capacity_more, demand), and\n# the smaller serves min(capacity_fewer, demand - served_more).\n# Profit = revenue - 2.0 * drones away from own base - 15.0 * drones bought.\n# Purchases use start-of-turn money, appear after moves, and cannot move that turn.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\n\ndef served(own, enemy, demand):\n    """The specification\'s exact revenue rule, from our point of view."""\n    a = 4 * own\n    b = 4 * enemy\n    if own == enemy:\n        denominator = max(a + b, demand)\n        return a * demand / denominator if denominator else 0.0\n    if own > enemy:\n        return min(a, demand)\n    return min(a, demand - min(b, demand))\n\n\ndef margin(own, enemy, demand):\n    return served(own, enemy, demand) - served(enemy, own, demand)\n\n\ndef preprocess(n, edges):\n    adj = [[] for _ in range(n)]\n    for u, v in edges:\n        adj[u].append(v)\n        adj[v].append(u)\n    for row in adj:\n        row.sort()\n    distances = []\n    for source in range(n):\n        dist = [n + 1] * n\n        dist[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adj[u]:\n                if dist[v] > n:\n                    dist[v] = dist[u] + 1\n                    queue.append(v)\n        distances.append(dist)\n    hops = [[s for _ in range(n)] for s in range(n)]\n    for s in range(n):\n        for target in range(n):\n            if target != s:\n                candidates = [\n                    v for v in adj[s]\n                    if distances[v][target] == distances[s][target] - 1\n                ]\n                if candidates:\n                    hops[s][target] = candidates[0]\n    return adj, distances, hops\n\n\ndef legal_action(assignments, have, base, adj, hops, money, build):\n    """Validate against a separate start-of-turn availability ledger."""\n    aggregated = {}\n    for source, target, count in assignments:\n        if source == target or count <= 0:\n            continue\n        destination = hops[source][target]\n        if destination in adj[source]:\n            key = (source, destination)\n            aggregated[key] = aggregated.get(key, 0) + count\n    available = list(have)\n    moves = []\n    for (source, destination), count in sorted(aggregated.items()):\n        if not (0 <= source < len(have) and 0 <= destination < len(have)):\n            continue\n        if destination not in adj[source]:\n            continue\n        count = min(int(count), available[source])\n        if count > 0:\n            available[source] -= count\n            moves.append((int(source), int(destination), int(count)))\n    build = max(0, min(int(build), 40 - sum(have)))\n    while build and build * 15.0 > money:\n        build -= 1\n    return {"moves": moves, "build": int(build)}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map = None\n        self.samples = []\n        self.sums = []\n        self.low = []\n        self.high = []\n        self.last_turn = None\n        self.enemy_memory = []\n        self.previous_visible = []\n        self.sticky = {}\n        self.motion = 0.3\n        self.bad_reports = 0\n\n    def estimate_means(self, demand, turn):\n        n = len(demand)\n        if not self.samples:\n            self.samples = [0] * n\n            self.sums = [0.0] * n\n            self.low = [1.0] * n\n            self.high = [10.0] * n\n        if turn != self.last_turn:\n            for v, value in enumerate(demand):\n                if value <= 0:\n                    continue\n                self.samples[v] += 1\n                self.sums[v] += value\n                # Each rounded observation bounds the unknown uniform-noise mean.\n                self.low[v] = max(self.low[v], (value - 0.05) / 1.5)\n                self.high[v] = min(self.high[v], (value + 0.05) / 0.5)\n        result = []\n        for v in range(n):\n            if demand[v] == 0:\n                result.append(0.0)\n            else:\n                lo, hi = self.low[v], self.high[v]\n                average = (self.sums[v] + 11.0) / (self.samples[v] + 2)\n                result.append(max(lo, min(hi, average)) if lo <= hi else average)\n        return result\n\n    def predict_enemy(self, obs, means, adj, dist):\n        n = len(means)\n        visible = obs["opponent_drones"]\n        turn = obs["turn"]\n        enemy_base = obs["opponent_base"]\n        if not self.enemy_memory:\n            self.enemy_memory = [(0, -100)] * n\n        changes = total = 0\n        if self.previous_visible:\n            for v in range(n):\n                old, new = self.previous_visible[v], visible[v]\n                if old is not None and new is not None:\n                    changes += abs(new - old)\n                    total += old + new\n            if total:\n                observed_motion = min(0.85, changes / total)\n                self.motion = 0.85 * self.motion + 0.15 * observed_motion\n        stay = [0] * n\n        for v, count in enumerate(visible):\n            if count is not None:\n                self.enemy_memory[v] = (int(count), turn)\n                stay[v] = int(count)\n            else:\n                count, seen = self.enemy_memory[v]\n                if turn - seen <= 2:\n                    stay[v] = count\n        # A local greedy model cannot move an enemy drone more than one edge.\n        predicted = [0] * n\n        own = obs["player_drones"]\n        for source in sorted(range(n), key=lambda v: (-stay[v], v)):\n            for _ in range(stay[source]):\n                best = source\n                best_gain = -1e100\n                for v in sorted([source] + adj[source]):\n                    k = predicted[v]\n                    gain = (\n                        served(k + 1, own[v], means[v])\n                        - served(k, own[v], means[v])\n                        - (0.0 if v == enemy_base else 2.0)\n                    )\n                    if v == source:\n                        gain += 0.15\n                    if gain > best_gain:\n                        best_gain, best = gain, v\n                predicted[best] += 1\n        self.previous_visible = list(visible)\n        return stay, predicted\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0001, 0.58 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        if self.map is None:\n            self.map = preprocess(n, obs["edges"])\n        adj, dist, hops = self.map\n        have = list(obs["player_drones"])\n        base = int(obs["player_base"])\n        turn = int(obs["turn"])\n        remaining = max(1, 120 - turn)\n        demand = list(obs["demand"])\n        means = self.estimate_means(demand, turn)\n        stay, predicted = self.predict_enemy(obs, means, adj, dist)\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n\n        horizon = min(remaining, 16)\n        weight = min(0.65, max(0.12, self.motion))\n        total = sum(have)\n        limit = min(40, total + 4)\n        future = [[0.0] * (limit + 1) for _ in range(n)]\n        current = [[0.0] * (limit + 1) for _ in range(n)]\n        for v in range(n):\n            upkeep = 0.0 if v == base else 2.0\n            for k in range(limit + 1):\n                value = 0.0\n                # Midpoint quadrature integrates the uniform demand noise.\n                for multiplier in (0.6, 0.8, 1.0, 1.2, 1.4):\n                    d = means[v] * multiplier\n                    value += ((1 - weight) * margin(k, stay[v], d)\n                              + weight * margin(k, predicted[v], d))\n                future[v][k] = value / 5.0 - upkeep * k\n                current[v][k] = (\n                    (1 - weight) * margin(k, stay[v], demand[v])\n                    + weight * margin(k, predicted[v], demand[v])\n                    - upkeep * k\n                )\n\n        counts = [0] * n\n        available = list(have)\n        assignments = []\n        next_sticky = {}\n\n        def gain(source, target, amount, h):\n            k = counts[target]\n            distance = dist[source][target]\n            delay = max(0, distance - 1)\n            earning_turns = h - delay\n            if earning_turns <= 0 or k + amount > limit:\n                return -1e100\n            delta = future[target][k + amount] - future[target][k]\n            value = earning_turns * delta - 2.0 * amount * delay\n            if distance <= 1:\n                value += (current[target][k + amount] - current[target][k] - delta)\n            if source == target:\n                value += 0.12 * amount * h\n            elif self.sticky.get((source, target), 0):\n                value += 0.08 * amount * h\n            return value\n\n        # Bundle marginals handle the discontinuity at an enemy fleet\'s size:\n        # crossing a tie can be profitable even when the first drone is not.\n        while sum(available) and time.perf_counter() < deadline:\n            best = None\n            best_rate = -1e100\n            for target in range(n):\n                sources = [s for s in range(n) if available[s]]\n                sources.sort(key=lambda s: (dist[s][target], -available[s], s))\n                for source in sources[:3]:\n                    maximum = min(5, available[source])\n                    for amount in range(1, maximum + 1):\n                        value = gain(source, target, amount, horizon)\n                        rate = value / amount\n                        if rate > best_rate:\n                            best_rate = rate\n                            best = (source, target, amount)\n            if best is None:\n                break\n            source, target, amount = best\n            available[source] -= amount\n            counts[target] += amount\n            assignments.append(best)\n            position = source if source == target else hops[source][target]\n            key = (position, target)\n            next_sticky[key] = next_sticky.get(key, 0) + amount\n\n        # Deadline fallback leaves unplanned units in place; it is always legal.\n        for source, amount in enumerate(available):\n            if amount:\n                counts[source] += amount\n\n        build = 0\n        money = float(obs.get("player_money", 0.0))\n        if remaining > 15 and self.bad_reports < 2:\n            affordable = max(0, min(2, 40 - total, int(max(0.0, money) // 15)))\n            for _ in range(affordable):\n                if time.perf_counter() >= deadline:\n                    break\n                best_target = None\n                best_value = 0.0\n                # A purchased drone spends this turn on base and only then travels.\n                for target in range(n):\n                    if target == base or counts[target] >= limit:\n                        continue\n                    d = dist[base][target]\n                    h = min(32, remaining - 1)\n                    value = gain(base, target, 1, h) - 15.0\n                    # Require a useful buffer against fog and model error.\n                    if d < remaining - 1 and value > best_value + 5.0:\n                        best_value, best_target = value, target\n                if best_target is None:\n                    break\n                build += 1\n                counts[best_target] += 1\n\n        self.sticky = next_sticky\n        self.last_turn = turn\n        return legal_action(assignments, have, base, adj, hops, money, build)\n'
