_FALLBACK_SRC = '# Exact action format: {"moves": [(from_node, to_node, count), ...], "build": n_buy}\n# Payout: "if n_0 == n_1", served_p is\n# capacity_p * demand / max(capacity_0 + capacity_1, demand).\n# Otherwise, "served_more = min(capacity_more, demand)" and\n# "served_fewer = min(capacity_fewer, demand - served_more)".\n# Costs: "upkeep_p = UPKEEP * (drones p owns - drones p has on its own base)"\n# and "profit_p = revenue_p - upkeep_p - BUILD_COST * (drones p bought this turn)".\n# This conservative fallback never buys and normally places only one drone per node.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 120\nDRONE_CAPACITY = 4\nUPKEEP = 2.0\n\n\ndef payout(own, opponent, demand):\n    """The specification\'s exact revenue rule, including the zero-demand case."""\n    if demand <= 0.0 or own <= 0:\n        return 0.0\n    capacity = DRONE_CAPACITY * own\n    other_capacity = DRONE_CAPACITY * opponent\n    if own == opponent:\n        return capacity * demand / max(capacity + other_capacity, demand)\n    if own > opponent:\n        return min(capacity, demand)\n    return min(capacity, demand - min(other_capacity, demand))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for neighbours in adjacency:\n        neighbours.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [n + 1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbour in adjacency[node]:\n                if distance[neighbour] == n + 1:\n                    distance[neighbour] = distance[node] + 1\n                    queue.append(neighbour)\n        distances.append(distance)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for destination in range(n):\n            if source == destination:\n                continue\n            for neighbour in adjacency[source]:\n                if distances[neighbour][destination] == distances[source][destination] - 1:\n                    next_hop[source][destination] = neighbour\n                    break\n    return adjacency, distances, next_hop\n\n\ndef make_plan(obs, distances, conservative=False):\n    """Return source/destination/count assignments, not chained moves."""\n    n = int(obs["n_nodes"])\n    base = int(obs["player_base"])\n    enemy_base = int(obs["opponent_base"])\n    demand = obs["demand"]\n    opponents = obs["opponent_drones"]\n    available = [int(x) for x in obs["player_drones"]]\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    occupied = [False] * n\n    assignments = []\n\n    # Keeping an established, unopposed one-drone station avoids chasing noise.\n    # No stored estimates or remembered destinations are needed.\n    for node in range(n):\n        if (\n            node != base\n            and available[node] > 0\n            and opponents[node] == 0\n            and payout(1, 0, float(demand[node])) >= 2.15\n        ):\n            available[node] -= 1\n            occupied[node] = True\n\n    candidates = []\n    if not conservative:\n        for node in range(n):\n            if node == base or node == enemy_base or occupied[node]:\n                continue\n            if opponents[node] not in (None, 0):\n                continue\n\n            # Unknown territory on the opponent\'s side is not worth a fight.\n            if distances[base][node] > distances[enemy_base][node]:\n                continue\n            if opponents[node] is None and distances[enemy_base][node] <= 2:\n                continue\n\n            # Rounded current demand supplies a rigorous lower bound on the\n            # hidden mean. Future demand is at least roughly one third of\n            # current demand. Include rounding slack at both ends.\n            guaranteed_demand = max(0.0, (float(demand[node]) - 0.051) / 3.0 - 0.051)\n            guaranteed_net = payout(1, 0, guaranteed_demand) - UPKEEP\n            if guaranteed_net >= 0.40:\n                candidates.append((node, guaranteed_net))\n\n    # Nearest-first placement. Each destination receives at most one drone.\n    # All travel turns are charged upkeep, with no assumed transit revenue.\n    pairs = []\n    for source in range(n):\n        if available[source] <= 0:\n            continue\n        for destination, guaranteed_net in candidates:\n            hops = distances[source][destination]\n            if hops <= 0 or hops > n:\n                continue\n            earning_turns = remaining - hops + 1\n            guaranteed_profit = (\n                earning_turns * guaranteed_net - UPKEEP * (hops - 1)\n            )\n            # Extra profit cushion prevents late, barely worthwhile trips.\n            if earning_turns > 0 and guaranteed_profit >= 5.0:\n                pairs.append((hops, destination, source))\n\n    pairs.sort()\n    for _, destination, source in pairs:\n        if occupied[destination] or available[source] <= 0:\n            continue\n        available[source] -= 1\n        occupied[destination] = True\n        assignments.append((source, destination, 1))\n\n    # Everything not safely earning goes home; never pay upkeep for a reserve.\n    for source in range(n):\n        if source != base and available[source] > 0:\n            assignments.append((source, base, available[source]))\n    return assignments\n\n\ndef legal_action(assignments, start_counts, adjacency, next_hop):\n    """Translate routes into one-edge moves and replay start-turn availability."""\n    aggregated = {}\n    for source, destination, count in assignments:\n        if source == destination or count <= 0:\n            continue\n        hop = next_hop[source][destination]\n        if hop < 0:\n            continue\n        key = (source, hop)\n        aggregated[key] = aggregated.get(key, 0) + int(count)\n\n    available = [int(x) for x in start_counts]\n    moves = []\n    n = len(available)\n    for (source, destination), requested in sorted(aggregated.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if source == destination or destination not in adjacency[source]:\n            continue\n        count = min(int(requested), available[source])\n        if count <= 0:\n            continue\n        available[source] -= count\n        moves.append((int(source), int(destination), int(count)))\n    return {"moves": moves, "build": int(0)}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": [], "build": 0}\n\n        # Only static map data is cached. Plans remain valid after skipped turns.\n        key = (n, tuple((int(u), int(v)) for u, v in obs.get("edges", [])))\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, key[1])\n            self.map_key = key\n\n        adjacency, distances, next_hop = self.map_data\n\n        # Any reported problem triggers the simpler action immediately, rather\n        # than risking repetition. This is intentionally more cautious than\n        # waiting for two reports and requires no dynamic strategy state.\n        conservative = (\n            not obs.get("action_format_correct_last_turn", True)\n            or int(obs.get("n_invalid_actions_last_turn", 0)) > 0\n        )\n        assignments = make_plan(obs, distances, conservative)\n        return legal_action(\n            assignments, obs["player_drones"], adjacency, next_hop\n        )\n'
